static void octeon_get_uboot_version ( struct octeon_device * oct ) { s32 bytes_read , tries , total_read ; struct octeon_console * console ; u32 console_num = 0 ; char * uboot_ver ; char * buf ; char * p ; buf = kmalloc ( OCTEON_UBOOT_VER_BUF_SIZE , GFP_KERNEL ) ; if ( ! buf ) { return ; } if ( octeon_console_send_cmd ( oct , "setenv stdout pci\n" , 50 ) ) { return ; } if ( octeon_console_send_cmd ( oct , "version\n" , 1 ) ) { kfree ( buf ) ; return ; } console = & oct -> console [ console_num ] ; tries = 0 ; total_read = 0 ; { bytes_read = octeon_console_read ( oct , console_num , buf + total_read , OCTEON_UBOOT_VER_BUF_SIZE - 1 - total_read ) ; if ( bytes_read > 0 ) { buf [ bytes_read ] = '\0' ; total_read += bytes_read ; if ( console -> waiting ) { octeon_console_handle_result ( oct , console_num ) ; } } if ( bytes_read < 0 ) { dev_err ( & oct -> pci_dev -> dev , "Error reading console %u, ret=%d\n" , console_num , bytes_read ) ; } tries ++ ; } ( bytes_read > 0 ) && ( tries < 16 ) ; if ( ( total_read == 0 ) && ( console -> leftover [ 0 ] ) ) { dev_dbg ( & oct -> pci_dev -> dev , "%u: %s\n" , console_num , console -> leftover ) ; console -> leftover [ 0 ] = '\0' ; } buf [ OCTEON_UBOOT_VER_BUF_SIZE - 1 ] = '\0' ; uboot_ver = strstr ( buf , "U-Boot" ) ; if ( uboot_ver ) { p = strstr ( uboot_ver , "mips" ) ; if ( p ) { p -- ; * p = '\0' ; dev_info ( & oct -> pci_dev -> dev , "%s\n" , uboot_ver ) ; } } kfree ( buf ) ; octeon_console_send_cmd ( oct , "setenv stdout serial\n" , 50 ) ; } 